  "sql": "SELECT p.product_id, p.product_name, SUM(oi.quantity) AS total_quantity FROM commerce.order_items AS oi JOIN commerce.orders AS o ON oi.order_id = o.order_id JOIN commerce.products AS p ON oi.product_id = p.product_id WHERE o.order_status <> 'cancelled' AND o.order_date >= $1 AND o.order_date < $2 GROUP BY p.product_id, p.product_name ORDER BY 3 DESC LIMIT 20",
  "parameters": ["2022-01-01", "2023-01-01"],
  "explanation": "Joins order_items with orders to filter out cancelled orders and restrict the date range to 2022. Joins with products to get product details. Sums the quantity for each product, orders by the total quantity in descending order, and limits the result to the top 20 products."
}

